<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {httpClient,authSession} from '@/shared/http/client'
const token=ref(''),password=ref(''),confirmPassword=ref(''),busy=ref(false),error=ref(''),success=ref(false),activatedUsername=ref(''),identity=ref<{username:string;displayName:string;roles:string[];shop?:string;loginUrl:string}>()
onMounted(async()=>{token.value=new URLSearchParams(location.hash.slice(1)).get('token')??'';history.replaceState(null,'',location.pathname+location.search);if(!token.value){error.value='请从工作人员提供的有效邀请链接打开，不能自行注册';return}busy.value=true;try{identity.value=(await httpClient.post('/auth/activation/inspect',{token:token.value})).data.data}catch(e){error.value=e instanceof Error?e.message:'邀请不可用'}finally{busy.value=false}})
async function activate(){if(busy.value||!identity.value)return;error.value='';if(!password.value.trim()||new TextEncoder().encode(password.value).length>72||password.value!==confirmPassword.value){error.value='密码须非空、不超过72个UTF8字节，且两次输入一致';return}busy.value=true;try{const response=await httpClient.post('/auth/activation/complete',{token:token.value,password:password.value,confirmPassword:confirmPassword.value});activatedUsername.value=response.data.data.username;success.value=true;token.value='';authSession.clear()}catch(e){error.value=e instanceof Error?e.message:'开通失败，请联系邀请人员核实'}finally{password.value='';confirmPassword.value='';busy.value=false}}
</script>
<template><main class="activation"><h1>账号开通</h1><p>仅接受工作人员邀请，角色与身份已由后台确定，不提供公众注册。</p><p v-if="busy" role="status">正在处理…</p><p v-if="error" role="alert">{{ error }}</p><section v-if="identity&&!success"><p>账号：{{ identity.username }}；姓名：{{ identity.displayName }}</p><p>身份：{{ identity.roles.join('、') }}<span v-if="identity.shop">；所属网点：{{ identity.shop }}</span></p><form @submit.prevent="activate"><label>设置密码<input v-model="password" type="password" autocomplete="new-password" :disabled="busy"></label><label>确认密码<input v-model="confirmPassword" type="password" autocomplete="new-password" :disabled="busy"></label><p>密码非空、最多72个UTF8字节。邀请24小时内一次有效，重发后旧链接失效。</p><button :disabled="busy">设置密码并激活</button></form></section><section v-if="success"><h2>账号已开通</h2><p>请保存登录账号：{{ activatedUsername }}，使用刚设置的密码登录。</p><a :href="identity?.loginUrl">前往登录</a></section><p>此页面不验证短信或证件，不代表合作网点入驻审核。链接不可用时请联系邀请人员；勿转发邀请凭据。</p></main></template>
<style scoped>.activation{max-width:520px;margin:32px auto;padding:24px;border:1px solid #ddd;border-radius:14px;background:white;line-height:1.7}.activation label{display:block;margin:16px 0}.activation input{display:block;width:100%;box-sizing:border-box;min-height:44px}.activation button,.activation a{display:inline-block;min-height:44px;padding:8px 16px}.activation [role=alert]{color:#a32222}@media(max-width:600px){.activation{margin:12px;padding:18px}}</style>
